## Updated implementation

```rust
use std::borrow::Borrow;
use std::hash::{BuildHasher, Hash};

use ahash::RandomState;
use crossbeam_utils::CachePadded;
use hashbrown::hash_map::RawEntryMut;
use hashbrown::HashMap;
use parking_lot::RwLock;

const DEFAULT_SHARDS: usize = 32;

type Shard<K, V, S> = CachePadded<RwLock<HashMap<K, V, S>>>;

pub struct ShardedMap<K, V, S = RandomState> {
    shards: Box<[Shard<K, V, S>]>,
    hasher: S,
    shard_mask: u64,
}

impl<K, V> ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    pub fn new() -> Self {
        Self::with_shards(DEFAULT_SHARDS)
    }

    pub fn with_shards(shards: usize) -> Self {
        Self::with_shards_and_hasher(shards, RandomState::new())
    }
}

impl<K, V, S> ShardedMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Clone,
{
    pub fn with_shards_and_hasher(shards: usize, hasher: S) -> Self {
        let shard_count = shards.max(1).next_power_of_two();
        let shards: Vec<_> = (0..shard_count)
            .map(|_| CachePadded::new(RwLock::new(HashMap::with_hasher(hasher.clone()))))
            .collect();
        Self {
            shards: shards.into_boxed_slice(),
            hasher,
            shard_mask: (shard_count - 1) as u64,
        }
    }

    pub fn shard_count(&self) -> usize {
        self.shards.len()
    }

    /// Hash the key exactly once. Reused for shard selection and bucket lookup.
    #[inline]
    fn hash<Q: Hash + ?Sized>(&self, key: &Q) -> u64 {
        self.hasher.hash_one(key)
    }

    #[inline]
    fn shard_for(&self, hash: u64) -> &Shard<K, V, S> {
        // Safe because shard_mask = len - 1 with len a power of two.
        &self.shards[(hash & self.shard_mask) as usize]
    }

    pub fn insert(&self, key: K, value: V) -> Option<V> {
        let hash = self.hash(&key);
        let mut shard = self.shard_for(hash).write();
        match shard.raw_entry_mut().from_key_hashed_nocheck(hash, &key) {
            RawEntryMut::Occupied(mut e) => Some(e.insert(value)),
            RawEntryMut::Vacant(e) => {
                e.insert_hashed_nocheck(hash, key, value);
                None
            }
        }
    }

    pub fn remove<Q>(&self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash(key);
        let mut shard = self.shard_for(hash).write();
        match shard.raw_entry_mut().from_key_hashed_nocheck(hash, key) {
            RawEntryMut::Occupied(e) => Some(e.remove()),
            RawEntryMut::Vacant(_) => None,
        }
    }

    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash(key);
        self.shard_for(hash)
            .read()
            .raw_entry()
            .from_key_hashed_nocheck(hash, key)
            .is_some()
    }

    pub fn get<Q>(&self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        V: Clone,
        Q: Hash + Eq + ?Sized,
    {
        let hash = self.hash(key);
        self.shard_for(hash)
            .read()
            .raw_entry()
            .from_key_hashed_nocheck(hash, key)
            .map(|(_, v)| v.clone())
    }

    pub fn with<Q, F, R>(&self, key: &Q, f: F) -> Option<R>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        F: FnOnce(&V) -> R,
    {
        let hash = self.hash(key);
        self.shard_for(hash)
            .read()
            .raw_entry()
            .from_key_hashed_nocheck(hash, key)
            .map(|(_, v)| f(v))
    }

    pub fn with_mut<Q, F, R>(&self, key: &Q, f: F) -> Option<R>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
        F: FnOnce(&mut V) -> R,
    {
        let hash = self.hash(key);
        let mut shard = self.shard_for(hash).write();
        match shard.raw_entry_mut().from_key_hashed_nocheck(hash, key) {
            RawEntryMut::Occupied(mut e) => Some(f(e.get_mut())),
            RawEntryMut::Vacant(_) => None,
        }
    }

    pub fn upsert<F>(&self, key: K, default: V, update: F)
    where
        F: FnOnce(&mut V),
    {
        let hash = self.hash(&key);
        let mut shard = self.shard_for(hash).write();
        match shard.raw_entry_mut().from_key_hashed_nocheck(hash, &key) {
            RawEntryMut::Occupied(mut e) => update(e.get_mut()),
            RawEntryMut::Vacant(e) => {
                e.insert_hashed_nocheck(hash, key, default);
            }
        }
    }

    pub fn len(&self) -> usize {
        self.shards.iter().map(|s| s.read().len()).sum()
    }

    pub fn is_empty(&self) -> bool {
        self.shards.iter().all(|s| s.read().is_empty())
    }

    pub fn clear(&self) {
        for shard in self.shards.iter() {
            shard.write().clear();
        }
    }

    pub fn for_each<F>(&self, mut f: F)
    where
        F: FnMut(&K, &V),
    {
        for shard in self.shards.iter() {
            let guard = shard.read();
            for (k, v) in guard.iter() {
                f(k, v);
            }
        }
    }
}

impl<K, V> Default for ShardedMap<K, V, RandomState>
where
    K: Hash + Eq,
{
    fn default() -> Self {
        Self::new()
    }
}
```

A few small things to note about the diff from the original:

- `unwrap()` is gone everywhere because `parking_lot` locks return guards directly.
- Every method computes the hash exactly once and threads it through `from_key_hashed_nocheck`.
- The `Shard` type alias keeps the cache padding visible without polluting every signature.

## When to push further

This handles most read-heavy workloads. If profiling still shows lock contention dominating:

- **Snapshot reads with `arc-swap`.** If writes are rare (config, routing tables, feature flags), wrap the inner map in `ArcSwap<HashMap<K, V>>`. Reads become a single atomic load with zero locking. Writers clone the whole map, mutate, and swap. Memory cost is one extra `Arc` per snapshot in flight, plus full-map clones on writes.
- **Eventually-consistent dual-buffer maps.** Crates like `left-right` give truly lock-free reads at the cost of read-staleness until the writer publishes. Good for caches and hot-path lookups where a few microseconds of staleness is fine.
- **Tune shard count.** A common heuristic is `shards = next_power_of_two(num_cpus * 4)`. Too few and you serialize writers; too many and you waste memory and warm cache lines unnecessarily.
- **Drop CachePadded.** If you have thousands of small shards or are memory-constrained, the padding becomes the dominant cost. Measure first.

The tradeoff worth remembering: `RwLock` sharding is the right default. `ArcSwap` and `left-right` win only when the read/write ratio is very lopsided, and they impose snapshot or staleness semantics that the caller has to be okay with.
